    import itertools
    V = vR2c if strict else vR1c
    Vc=[]
    for r in range(2,62):
        for c in range(2,62):
            if V([(r,c)],B): Vc.append((r,c))
    Vset=set(Vc)
    k=len(chain)
    idx=[i for i in range(k) if i not in keep]
    kr=sum(chain[i][0] for i in keep); kc=sum(chain[i][1] for i in keep)
    sol=[]; cnt=[0]
    def rec(order, assign, path, last_i):
        if sol or cnt[0]>150000: return
        cnt[0]+=1
        if not order:
            others=[v for j,v in assign.items() if j!=last_i]
            cr=sum(v[0] for v in others); cc=sum(v[1] for v in others)
            for sr in range(tr[0]-kr-cr, tr[1]-kr-cr+1):
                for sc in range(tc[0]-kc-cc, tc[1]-kc-cc+1):
                    t=(sr,sc)
                    if t not in Vset: continue
                    na=dict(assign); na[last_i]=t
                    newpos=[na.get(j,chain[j]) for j in range(k)]
                    if V(newpos,B): sol.append(path[:-1]+[(chain[last_i],t)])
                    if sol: return
            return
        for pos_i,i in enumerate(order):
